import React, { useContext } from "react";
import { useFormik } from "formik";
import axios from "axios";
import { formSchema } from "../validation/schema";
import { AppContext } from "../context/AppContext";

const TranslationForm = () => {
  const { addRecord } = useContext(AppContext);

  const formik = useFormik({
    initialValues: {
      prompt: "",
      targetLanguage: ""
    },

    validationSchema: formSchema,

    onSubmit: async (values, { resetForm }) => {
      try {
        const response = await axios.post(
          "http://localhost:5000/api/translate",
          values
        );

        addRecord({
          request: values,
          response: response.data
        });

        resetForm();

      } catch (error) {
        console.error("API Error:", error);
      }
    }
  });
  const formStyle = {
    backgroundColor: 'rgb(205 224 227)',
    padding: '20px',
    borderRadius: '8px',
    transition: 'background-color 0.3s ease',
  };
  return (
    <form style={formStyle} onSubmit={formik.handleSubmit}>

      <div>
        <label>Prompt</label>
        <input
          type="text"
          name="prompt"
          value={formik.values.prompt}
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
        />

        {formik.touched.prompt &&
          formik.errors.prompt && (
            <p>{formik.errors.prompt}</p>
        )}
      </div>

      <div>
        <label>Target Language</label>

        <select
          name="targetLanguage"
          value={formik.values.targetLanguage}
          onChange={formik.handleChange}
          onBlur={formik.handleBlur}
        >
          <option value="">Select Language</option>
          <option value="en">English</option>
          <option value="es">Spanish</option>
          <option value="fr">French</option>
        </select>

        {formik.touched.targetLanguage &&
          formik.errors.targetLanguage && (
            <p>{formik.errors.targetLanguage}</p>
        )}
      </div>

      <button
        type="submit"
        disabled={!formik.isValid || !formik.dirty}
      >
        Submit
      </button>

    </form>
  );
};

export default TranslationForm;
